  day: [['jet', 3], ['show', 2], ['heli', 2], ['rocket', 2], ['birds', 3], ['eagle', 2.5], ['balloon', 1.5], ['paper', 2], ['banner', 1.5], ['abduct', 2.2], ['rainbow', 1.5]],
