    const pts = [];
    segs.forEach((s, si) => { const [a, b, c, d] = s.p, n = s.n || 8; for (let i = si ? 1 : 0; i <= n; i++) { const u = i / n, v = 1 - u, A = v * v * v, B = 3 * v * v * u, C = 3 * v * u * u, D = u * u * u; pts.push({ x: A * a[0] + B * b[0] + C * c[0] + D * d[0], y: A * a[1] + B * b[1] + C * c[1] + D * d[1], o: s.t[0] + (s.t[1] - s.t[0]) * u }); } });
